package com.tradepilot.backtest.service;
import com.tradepilot.backtest.model.BacktestBar; import com.tradepilot.marketdata.*; import com.tradepilot.marketdata.entity.MarketBar; import com.tradepilot.marketdata.model.MarketInstrument; import com.tradepilot.marketdata.repository.MarketBarRepository; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class BacktestDataService { private final MarketBarRepository bars; public BacktestDataService(MarketBarRepository bars){this.bars=bars;} public List<BacktestBar> load(MarketInstrument i,LocalDate start,LocalDate end){Instant s=start.minusDays(28).atStartOfDay(ZoneOffset.UTC).toInstant(),e=end.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(); List<MarketBar> rows=bars.findBySymbolAndTimeframeAndTsEventGreaterThanEqualAndTsEventLessThanOrderByTsEventAsc(i,"1m",s,e); if(rows.isEmpty())throw new MarketDataException(org.springframework.http.HttpStatus.CONFLICT,"BACKTEST_DATA_INCOMPLETE","Historical data is incomplete for this range. Update Market Data first."); return rows.stream().map(b->new BacktestBar(b.getTsEvent(),b.getInstrumentId(),b.getOpen(),b.getHigh(),b.getLow(),b.getClose(),b.getVolume())).toList();} }
